# Вопрос-рамка для каждой группы — задаётся отдельным сообщением на группу,
# вместо одного сообщения с 13 пунктами и 5 заголовками сразу (было тяжело
# читать и выбирать). Каждая группа — свой шаг, с "Дальше" вместо мгновенного
# показа всего списка целиком.
PROBLEM_GROUP_INTRO = {
    0: "Бывают у тебя такие ситуации?",
    1: "А с этим бывает трудно?",
    2: "Как насчёт этого?",
    3: "И ещё один момент.",
    4: "Последнее — как у тебя с этим?",
}

def problem_group_kb(group_idx, selected):
    _, keys = PROBLEM_GROUPS[group_idx]
    is_last = group_idx == len(PROBLEM_GROUPS) - 1
    rows = []
    for key in keys:
        mark = "✅ " if key in selected else "▫️ "
        rows.append([InlineKeyboardButton(mark + PROBLEM_LABELS[key], callback_data=f"pt_{group_idx}_{key}")])
    if is_last:
        rows.append([InlineKeyboardButton("Готово ✅", callback_data="prob_done")])
    else:
        rows.append([InlineKeyboardButton("Дальше →", callback_data=f"pn_{group_idx}")])
    return InlineKeyboardMarkup(rows)

async def send_problem_group(message, ctx, group_idx):
    title, _ = PROBLEM_GROUPS[group_idx]
    selected = ctx.user_data.get("onboard_problems", [])
    intro = PROBLEM_GROUP_INTRO.get(group_idx, "Бывают у тебя такие ситуации?")
    await message.reply_text(
        f"*{title}*\n\n{intro}",
        parse_mode="Markdown",
        reply_markup=problem_group_kb(group_idx, selected)
    )

MID_PROCR_OPTIONS = [
    ("mid_nostart", "❓ Непонятно с чего начать"),
    ("mid_scary",   "😰 Задача подавляет/пугает"),
    ("mid_waiting", "⏳ Жду подходящего момента"),
    ("mid_perfect", "🎯 Боюсь сделать плохо"),
    ("mid_resist",  "🧱 Внутреннее сопротивление"),
    ("mid_time",    "⚡ Мало времени"),
    ("mid_phone",   "📱 Залип(ла) в телефоне"),
]

def mid_procr_kb(struggles, gender):
    """Варианты ветки «Прокрастинирую» — если при онбординге отмечены
    релевантные трудности (PROBLEM_TO_MID), они поднимаются наверх списка,
    остальные идут следом в исходном порядке. Без выбранных трудностей —
    порядок как раньше."""
    priority = []
    for s in struggles:
        priority.extend(PROBLEM_TO_MID.get(s, []))
    priority_set = dict.fromkeys(priority)
    ordered = [opt for opt in MID_PROCR_OPTIONS if opt[0] in priority_set] + \
              [opt for opt in MID_PROCR_OPTIONS if opt[0] not in priority_set]
    rows = [[InlineKeyboardButton(personalize(label, gender), callback_data=cb)] for cb, label in ordered]
    rows.append([InlineKeyboardButton("🤖 Коуч", callback_data="mid_coach")])
    return InlineKeyboardMarkup(rows)

