def get_diary(uid, block, for_date=None):
    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    d = for_date or date.today().isoformat()
    c.execute("SELECT data FROM diary WHERE user_id=? AND date=? AND block=?", (uid, d, block))
    row = c.fetchone()
