    ("stop",        "🛑 Навык СТОП"),
    ("first_step",  "👣 Первый маленький шаг"),
    ("activation",  "⚡ Активация"),
    ("rest",        "😴 Запланированный отдых"),
    ("anchor",      "⚓ Бросить якорь"),
    ("notes",       "📝 Бумажка гениальных мыслей"),
    ("environment", "🏠 Изменение среды"),
