# Шаги вечернего диалога по порядку, для резюме прерванного вечера — тот же
# принцип, что и RESUME_FIELDS для утра (см. комментарий там). Чек-лист задач
# (E_TASKS_DONE) сюда не входит — как и утренняя разминка, при прерывании на
# этом шаге ничего не жалко потерять, просто перетыкать чек-боксы заново.
# e_selfcare_done — отдельный маркер завершения (не сам "e_selfcare", он
# устанавливается уже при ВХОДЕ в шаг, до того как человек что-то отметил).
RESUME_FIELDS_EVENING = [
    ("e_ach",           E_ACH,        lambda msg, ctx, gender: ask_achievements(msg, gender)),
    ("e_praise",        E_PRAISE,     lambda msg, ctx, gender: ask_praise(msg)),
    ("e_highlights",    E_HIGHLIGHTS, lambda msg, ctx, gender: ask_highlights(msg)),
    ("e_selfcare_done", E_SELFCARE,   lambda msg, ctx, gender: ask_selfcare(msg, ctx, gender)),
    ("e_energy",        E_ENERGY,     lambda msg, ctx, gender: ask_energy(msg, gender)),
    ("e_a",             E_A,          lambda msg, ctx, gender: ask_plan_a(msg)),
    ("e_b1",            E_B1,         lambda msg, ctx, gender: msg.reply_text("🅱️ *Задача B1 на завтра:*", parse_mode="Markdown", reply_markup=skip_kb("skip_e_b1"))),
    ("e_b2",            E_B2,         lambda msg, ctx, gender: msg.reply_text("🅱️ *Задача B2:*", parse_mode="Markdown", reply_markup=skip_kb("skip_e_b2"))),
    ("e_c1",            E_C1,         lambda msg, ctx, gender: ask_e_c1(msg)),
    ("e_c2",            E_C2,         lambda msg, ctx, gender: msg.reply_text("🅲 *C2:*", parse_mode="Markdown", reply_markup=skip_kb("skip_e_c_all"))),
    ("e_c3",            E_C3,         lambda msg, ctx, gender: msg.reply_text("🅲 *C3:*", parse_mode="Markdown", reply_markup=skip_kb("skip_e_c_all"))),
]

async def advance_evening(ctx, message, gender, uid, from_key=None):
    """Переходит к следующему шагу вечернего ритуала после from_key (или с
    самого начала, если from_key=None) — см. advance_morning, тот же принцип.
    Чек-лист техник (e_selfcare) дополнительно пропускается для тех, кто
    закрывает вечер первый раз в жизни (has_any_diary_ever) — те же техники,
    что и в чек-листе выше, новичку ещё незнакомы."""
    user = get_user(uid)
    start_idx = 0
    if from_key is not None:
        start_idx = next(i for i, (k, _, _) in enumerate(RESUME_FIELDS_EVENING) if k == from_key) + 1
    for key, state, ask_fn in RESUME_FIELDS_EVENING[start_idx:]:
        toggle_name = {v: k for k, v in _TOGGLE_TO_RESUME_KEY.items()}.get(key, key)
        if key == "e_selfcare_done" and not has_any_diary_ever(uid):
            ctx.user_data[key] = True
            continue
        if is_field_disabled(user, toggle_name):
            ctx.user_data[key] = True if key == "e_selfcare_done" else ""
            continue
        await ask_fn(message, ctx, gender)
        return state
    await finish_evening(message, uid, ctx)
    return ConversationHandler.END

def checkpoint_evening_progress(ctx, uid, for_date):
    """Сохраняет недописанный вечер, прерванный и не продолженный в тот же
    день, в дневник этого дня как есть — без стрика и без побочных эффектов
    finish_evening (это не завершение дня, а спасение того, что успели
    заполнить). tasks_done намеренно не трогаем: список того, что реально
    делали, мог наполниться отдельно (дневной чекин), и его нельзя молча
    затирать пустым."""
    data = {k: ctx.user_data.get(k, "") for k in
            ["e_ach","e_praise","e_highlights","e_a","e_b1","e_b2","e_c1","e_c2","e_c3"]}
    data["e_selfcare"] = ctx.user_data.get("e_selfcare", [])
    data["e_energy"] = ctx.user_data.get("e_energy", 0)
    data["e_tasks_done"] = ctx.user_data.get("e_tasks_done", [])
    save_diary(uid, "evening", data, for_date=for_date)

async def finish_evening(message, uid, ctx):
    user = get_user(uid)
    tz = get_user_tz(user)
    today = evening_day(tz).isoformat()
    data = {k: ctx.user_data.get(k, "") for k in
            ["e_ach","e_praise","e_highlights","e_a","e_b1","e_b2","e_c1","e_c2","e_c3"]}
    data["e_selfcare"] = ctx.user_data.get("e_selfcare", [])
    data["e_energy"] = ctx.user_data.get("e_energy", 0)
    data["e_tasks_done"] = ctx.user_data.get("e_tasks_done", [])
    save_diary(uid, "evening", data, for_date=today)
    # Синхронизируем с "tasks_done" — источником для дневного меню "📋 Задачи",
    # чтобы отметки, поставленные здесь вечером, тоже были видны там.
    save_diary(uid, "tasks_done", {"done": data["e_tasks_done"]}, for_date=today)
    add_streak(uid, for_date=today)
    await unpin_today_tasks(ctx, uid)
    streak = calc_streak(uid)

    plans = ""
    if data["e_a"]:  plans += f"\n🅰️ {md_escape(data['e_a'])}"
    if data["e_b1"]: plans += f"\n🅱️ {md_escape(data['e_b1'])}"
    if data["e_b2"]: plans += f"\n🅱️ {md_escape(data['e_b2'])}"
    if data["e_c1"]: plans += f"\n🅲 {md_escape(data['e_c1'])}"

    tasks_summary = ""
    morning_for_summary = get_diary(uid, "morning", today)
    if any(morning_for_summary.get(k) for k, _ in TASK_FIELDS):
        done = set(data["e_tasks_done"])
        lines = []
        for key, icon in TASK_FIELDS:
            text = morning_for_summary.get(key)
            if not text: continue
            mark = "✅" if key in done else "▫️"
            lines.append(f"{mark} {icon} {md_escape(text)}")
        if lines:
            tasks_summary = "\n\n📋 *Задачи дня:*\n" + "\n".join(lines)

    selfcare_summary = ""
    if data["e_selfcare"]:
        labels = dict(SELFCARE_ITEMS)
        used = [labels[k] for k in data["e_selfcare"] if k in labels]
        if used:
            applied = g(user["gender"], "применял", "применяла")
            selfcare_summary = f"\n\n🧩 *Сегодня {applied}:*\n" + "\n".join(used)

    # AI анализ дня
    ai_analysis = ""
    if ANTHROPIC_KEY:
        morning = get_diary(uid, "morning", today)
        ai_analysis = await ai_day_analysis(user["name"], user["gender"], morning, data)
        if ai_analysis: ai_analysis = f"\n\n🤖 *Анализ дня:*\n_{ai_analysis}_"

    try:
        await message.reply_text(
            "✅ *День закрыт!*\n\n"
            f"🔥 Стрик: *{streak} {'день' if streak==1 else 'дня' if streak<5 else 'дней'}*\n"
            f"{tasks_summary}"
            f"\n\n{'📋 *Планы на завтра:*' + plans if plans else ''}"
            f"{selfcare_summary}"
            f"{ai_analysis}\n\n"
            f"_Молодец. До завтра, {user['name']}_ 👋",
            parse_mode="Markdown",
            reply_markup=menu_button_kb()
        )
    except Exception as e:
        # См. комментарий в finish_morning — не даём сбою отправки итога
        # оставить ConversationHandler в подвисшем состоянии.
        print(f"Ошибка отправки итога вечера uid={uid}: {e}")
        await message.reply_text(
            f"✅ День закрыт! 🔥 Стрик: {streak}. До завтра, {user['name']} 👋",
            reply_markup=menu_button_kb()
        )

# ── AI FUNCTIONS ───────────────────────────────────────────────────────────
async def ai_morning_boost(name, gender, focus):
    """Короткая AI-мотивация утром на основе фокуса."""
    if not ANTHROPIC_KEY: return ""
    try:
        from anthropic import Anthropic
        client = Anthropic(api_key=ANTHROPIC_KEY)
        gender_hint = "женского рода" if gender == 'F' else "мужского рода"
        resp = client.messages.create(
            model="claude-sonnet-4-5",
            max_tokens=150,
            system=f"Ты поддерживающий коуч. Пользователь: {name}, {gender_hint}, СДВГ. Пиши по-русски, 1-2 предложения, конкретно и тепло.",
            messages=[{"role":"user","content":f"Моя главная задача сегодня: {focus}. Дай короткий мотивирующий посыл."}]
        )
        return resp.content[0].text.strip()
    except: return ""

async def ai_day_analysis(name, gender, morning_data, evening_data):
    """AI-анализ прожитого дня вечером."""
    if not ANTHROPIC_KEY: return ""
    try:
        from anthropic import Anthropic
        client = Anthropic(api_key=ANTHROPIC_KEY)
        gender_hint = "женского рода" if gender == 'F' else "мужского рода"
        context = f"Утренний фокус: {morning_data.get('focus','не задан')}\n"
        if evening_data.get("e_ach"): context += f"Достижения: {evening_data['e_ach']}\n"
        if evening_data.get("e_highlights"): context += f"Яркие моменты: {evening_data['e_highlights']}\n"
        done = set(evening_data.get("e_tasks_done", []))
        task_lines = [morning_data[k] for k, _ in TASK_FIELDS if morning_data.get(k)]
        if task_lines:
            done_lines = [morning_data[k] for k, _ in TASK_FIELDS if morning_data.get(k) and k in done]
            context += f"Запланированные задачи: {'; '.join(task_lines)}\n"
            context += f"Выполнено из них: {'; '.join(done_lines) if done_lines else 'ничего не отмечено выполненным'}\n"
        resp = client.messages.create(
            model="claude-sonnet-4-5",
            max_tokens=400,
            system=(
                f"Ты коуч для {name} ({gender_hint}), у которой/которого СДВГ. Анализируй день кратко и тепло. "
                "Максимум 3 предложения, одним абзацем, без заголовков и без разметки (никаких **, ##, списков) — "
                "текст уже оборачивается в курсив снаружи. Отмечай прогресс и дай один конкретный совет на завтра. "
                "Пиши по-русски."
            ),
            messages=[{"role":"user","content":f"Вот мой день:\n{context}\nДай короткий анализ."}]
        )
        return resp.content[0].text.strip()
    except: return ""

COACH_HISTORY_LIMIT = 10  # последние 5 обменов (user+assistant) — коуч помнит контекст диалога, но токены не раздуваются

async def send_coach(message, text, uid, ctx=None):
    """Отправить запрос AI-коучу.

    ctx (если передан) хранит историю диалога в user_data["coach_history"],
    чтобы коуч помнил, о чём уже говорили в этой сессии, а не отвечал на
    каждое сообщение с нуля, теряя нить (жалоба: "сильно тупил" — ответы
    не учитывали предыдущие реплики)."""
    if not ANTHROPIC_KEY:
        await message.reply_text("⚠️ ИИ-коуч не настроен. Добавь ANTHROPIC_KEY в переменные Railway.", reply_markup=menu_button_kb())
        return
    user = get_user(uid)
    gender_hint = "женского рода" if user["gender"] == 'F' else "мужского рода"
    today, morning, done_set = get_today_context(user)
    tasks = build_tasks_summary(morning, done_set)
    tasks_hint = (
        f"\n\nЗадачи пользователя на сегодня:\n{tasks}\n"
        "Если из сообщения понятно, к какой задаче относится проблема — обращайся к ней прямо по названию. "
        "Если неясно и задач больше одной — сначала кратко переспроси, к какой из них вопрос."
        if tasks != "_задачи не заданы_" else ""
    )
    skill = get_daily_skill(uid)
    skill_hint = f"\n\nНавык дня у пользователя сегодня: {skill['name']} — {skill['desc']}. Если он в тему ситуации — предложи именно его."
    skill_names = ", ".join(s["name"] for s in SKILLS)

    history = ctx.user_data.get("coach_history", []) if ctx is not None else []
    thinking = await message.reply_text("🤖 думаю...")
    try:
        from anthropic import Anthropic
        client = Anthropic(api_key=ANTHROPIC_KEY)
        resp = client.messages.create(
            model="claude-sonnet-4-5",
            max_tokens=300,
            system=(
                f"Ты коуч для {user['name']} ({gender_hint}) с СДВГ. Начни с одной короткой фразы, "
                "которая показывает, что ты понимаешь ситуацию человека — по-человечески, не как диагноз "
                "(не используй клинические ярлыки вроде «паттерн», «избегание», «прокрастинация» как "
                "оценку его поведения — это звучит как разбор, а не поддержка). Дальше — одно ясное "
                "действие. Всего 2-4 предложения, без воды и без повторения того, что уже советовал(а) "
                "в этом диалоге. Никогда не морализируй и не стыди, даже мягко. "
                f"Техники, которые можно предлагать: {skill_names}."
                f"{tasks_hint}{skill_hint}\n\nПиши по-русски."
            ),
            messages=history + [{"role": "user", "content": text}]
        )
        reply_text = resp.content[0].text
        if ctx is not None:
            history = history + [{"role": "user", "content": text}, {"role": "assistant", "content": reply_text}]
            ctx.user_data["coach_history"] = history[-COACH_HISTORY_LIMIT:]
        await thinking.edit_text(
            f"🤖 {reply_text}",
            reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("◀️ Меню", callback_data="go_menu")]])
        )
    except Exception as e:
        await thinking.edit_text(f"Ошибка: {e}")

