async def reroll_skill_callback(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """«🔄 Поменять навык» — берёт следующий навык из того же пула
    (см. reroll_daily_skill) и присылает новой карточкой, с той же кнопкой,
    чтобы можно было прокрутить ещё раз, если и этот не подходит."""
    q = update.callback_query; await q.answer()
    uid = q.from_user.id
    skill = reroll_daily_skill(uid)
    skill_idx = SKILLS.index(skill)
    await q.message.reply_text(
        f"🔄 *Новый навык дня:* {skill['name']}\n_{skill['desc']}_",
        parse_mode="Markdown",
        reply_markup=InlineKeyboardMarkup([
            [InlineKeyboardButton(f"🧠 Подробнее: {skill['name']}", callback_data=f"skill_{skill_idx}")],
            [InlineKeyboardButton("🔄 Поменять навык", callback_data="reroll_skill")],
        ])
    )

async def show_skill_detail(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query; await q.answer()
    idx = int(q.data.replace("skill_", ""))
    skill = SKILLS[idx]

    animation_path = SKILL_ANIMATIONS.get(skill["name"])
    if animation_path:
        try:
            cached_id = _skill_animation_file_ids.get(skill["name"])
            sent_anim = await q.message.reply_animation(animation=cached_id or open(animation_path, "rb"))
            if not cached_id and sent_anim.animation:
                _skill_animation_file_ids[skill["name"]] = sent_anim.animation.file_id
        except Exception as e:
            print(f"Ошибка отправки анимации навыка {skill['name']}: {e}")

    buttons = [[InlineKeyboardButton("◀️ К списку навыков", callback_data="go_skill")]]
    if "Работа по таймеру" in skill["name"]:
        buttons.insert(0, [InlineKeyboardButton("🍅 Запустить таймер", callback_data="go_focus")])
    if skill["name"] == "🌬 Дыхание":
        # Два разных ритма дыхания в одном навыке — 4-8 присылается автоматически
        # выше, дыхание квадратом 4-4-4-4 по кнопке, чтобы не грузить два gif сразу.
        buttons.insert(0, [InlineKeyboardButton("🔲 Дыхание квадратом (4-4-4-4)", callback_data="skill_box_breathing")])
    buttons.append([InlineKeyboardButton("◀️ Меню", callback_data="go_menu")])
    gender = get_user(q.from_user.id)["gender"]
    await q.message.reply_text(
        f"🧠 *{skill['name']}*\n\n"
        f"📖 *Описание*\n{personalize(skill['explanation'], gender)}\n\n"
        f"✅ *Инструкция*\n{personalize(skill['instructions'], gender)}\n\n"
        "_Методика: когнитивно-поведенческая терапия для взрослых с СДВГ — «Mastering Your Adult ADHD» (Safren)_",
        parse_mode="Markdown",
        reply_markup=InlineKeyboardMarkup(buttons)
    )

async def show_box_breathing(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query; await q.answer()
    animation_path = os.path.join(ANIMATIONS_DIR, "box_breathing.gif")
    try:
        cached_id = _skill_animation_file_ids.get("box_breathing")
        sent_anim = await q.message.reply_animation(
            animation=cached_id or open(animation_path, "rb"),
            caption=(
                "🔲 *Дыхание квадратом*\n\n"
                "Вдох 4 — задержка 4 — выдох 4 — задержка 4. Точка идёт по сторонам квадрата.\n\n"
                "📖 *Почему это работает*\n"
                "Задержки дыхания — не пауза ради паузы, а дополнительный тормоз: они замедляют дыхание "
                "сильнее, чем обычный вдох-выдох, и продлевают сигнал безопасности блуждающему нерву, "
                "который переключает нервную систему в спокойный режим. Ровный счёт на 4 стороны легко "
                "удерживать в голове — не нужно решать самому, когда вдыхать, а когда выдыхать, мозг просто "
                "следует за квадратом. Этой техникой пользуются спецназ и врачи перед стрессовыми "
                "ситуациями — она работает быстро и не требует опыта медитации.\n\n"
                "⏱ *Сколько делать:* 4-5 циклов подряд (около 1-2 минут). При сильной тревоге можно "
                "продолжать дольше, до 5 минут.\n\n"
                "✅ Используй перед сложным разговором, во время тревоги или чтобы быстро успокоиться."
            ),
            parse_mode="Markdown"
        )
        if not cached_id and sent_anim.animation:
            _skill_animation_file_ids["box_breathing"] = sent_anim.animation.file_id
    except Exception as e:
        print(f"Ошибка отправки анимации дыхания квадратом: {e}")

